{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01439XnFYxG3ZyR97WUpUBib","type":"tool_result","content":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-core</repo>\n<path>packages/framework/esm-styleguide/src/workspaces2/workspace2.ts</path>\n<url>undefined</url>\n<content>\n1: import { type Context, useContext } from 'react';\n2: import { SingleSpaContext } from 'single-spa-react';\n3: import { v4 as uuidV4 } from 'uuid';\n4: import {\n5:   getGroupByWindowName,\n6:   getOpenedWindowIndexByWorkspace,\n7:   getWindowByWorkspaceName,\n8:   type OpenedWindow,\n9:   type OpenedWorkspace,\n10:   workspace2Store,\n11:   type WorkspaceStoreState2,\n12: } from '@openmrs/esm-extensions';\n13: import { type WorkspaceDefinition2 } from '@openmrs/esm-globals';\n14: import { useStoreWithActions, type Actions } from '@openmrs/esm-react-utils';\n15: import { shallowEqual } from '@openmrs/esm-utils';\n16: import { showModal } from '../modals';\n17: import { type Workspace2DefinitionProps } from './workspace2.component';\n18: \n19: /**\n20:  * Attempts to launch the specified workspace group with the given group props. Note that only one workspace group\n21:  * may be opened at any given time. If a workspace group is already opened, calling `launchWorkspaceGroup2` with\n22:  * either a different group name, or same group name but different incompatible props**, will result in prompting to\n23:  * confirm closing workspaces. If the user confirms, the opened group, along with its windows (and their workspaces), is closed, and\n24:  * the requested group is immediately opened.\n25:  *\n26:  * ** 2 sets of props are compatible if either one is nullish, or if they are shallow equal.\n27:  * @param groupName\n28:  * @param groupProps\n29:  * @returns a Promise that resolves to true if the specified workspace group with the specified group props\n30:  *  is successfully opened, or that it already is opened.\n31:  */\n32: export async function launchW